import React, { useState } from 'react';

// Create the StateMachineUI component here
const StateMachineUI = () => {
  // Define the finite state machine states here
  const [currentState, setCurrentState] = useState('IDLE');

  // Create state transition functions here
  const transitionToLoading = () => setCurrentState('LOADING');
  const transitionToSuccess = () => setCurrentState('SUCCESS');
  const transitionToError = () => setCurrentState('ERROR');

  // Add a reset function here
  const resetState = () => setCurrentState('IDLE');

  return (
    <div>
      {/* Add paragraph here */}
      <p>Current state: {currentState}</p>

      {/* Add state transition buttons here */}
      <button onClick={transitionToLoading}>Load</button>
      <button onClick={transitionToSuccess}>Success</button>
      <button onClick={transitionToError}>Error</button>
      <button onClick={resetState}>Reset</button>

      {/* Add conditional UI based on state here */}
    </div>
  );
};
